import { expect } from 'chai';
import { fieldExpression, stringExpression, valueExpression } from 'dash-table/syntax-tree/lexeme/expression';
describe('expression', () => {
    it('resolves field expression', () => {
        expect(!!fieldExpression.resolve).to.equal(true);
        expect(typeof fieldExpression.resolve).to.equal('function');
        if (fieldExpression.resolve) {
            expect(fieldExpression.resolve({ abc: 3 }, {
                value: '{abc}'
            })).to.equal(3);
            expect(fieldExpression.resolve({ 'a bc': 3 }, {
                value: '{a bc}'
            })).to.equal(3);
            expect(fieldExpression.resolve({ '{abc}': 3 }, {
                value: '{\\{abc\\}}'
            })).to.equal(3);
            expect(fieldExpression.resolve({ '"abc"': 3 }, {
                value: '{"abc"}'
            })).to.equal(3);
            expect(fieldExpression.resolve({ abc: 3 }, {
                value: '{def}'
            }) === undefined).to.equal(true);
            expect(fieldExpression.resolve({ abc: 3 }, {
                value: '{a bc}'
            }) === undefined).to.equal(true);
            expect(fieldExpression.resolve({ abc: 3 }, {
                value: '{"abc"}'
            }) === undefined).to.equal(true);
            expect(fieldExpression.resolve.bind(undefined, {}, {
                value: '3'
            })).to.throw();
            expect(fieldExpression.resolve.bind(undefined, {}, {
                value: 'abc'
            })).to.throw();
            expect(fieldExpression.resolve.bind(undefined, {}, {
                value: '{abc'
            })).to.throw();
            expect(fieldExpression.resolve.bind(undefined, {}, {
                value: 'abc}'
            })).to.throw();
            expect(fieldExpression.resolve.bind(undefined, {}, {
                value: '}abc{'
            })).to.throw();
            expect(fieldExpression.resolve.bind(undefined, {}, {
                value: '{{abc}}'
            })).to.throw();
            expect(fieldExpression.resolve.bind(undefined, {}, {
                value: '"'
            })).to.throw();
            expect(fieldExpression.resolve.bind(undefined, {}, {
                value: '`'
            })).to.throw();
            expect(fieldExpression.resolve.bind(undefined, {}, {
                value: "'"
            })).to.throw();
            expect(fieldExpression.resolve.bind(undefined, {}, {
                value: '{'
            })).to.throw();
            expect(fieldExpression.resolve.bind(undefined, {}, {
                value: '}'
            })).to.throw();
        }
    });
    it('resolves string expressions', () => {
        expect(!!stringExpression.resolve).to.equal(true);
        expect(typeof stringExpression.resolve).to.equal('function');
        if (stringExpression.resolve) {
            expect(stringExpression.resolve(undefined, {
                value: "''"
            })).to.equal('');
            expect(stringExpression.resolve(undefined, {
                value: "'abc'"
            })).to.equal('abc');
            expect(stringExpression.resolve(undefined, {
                value: '"abc"'
            })).to.equal('abc');
            expect(stringExpression.resolve(undefined, {
                value: '`abc`'
            })).to.equal('abc');
            expect(stringExpression.resolve(undefined, {
                value: '"\\""'
            })).to.equal('"');
            expect(stringExpression.resolve(undefined, {
                value: "'\\''"
            })).to.equal("'");
            expect(stringExpression.resolve(undefined, {
                value: '`\\``'
            })).to.equal('`');
            expect(stringExpression.resolve(undefined, {
                value: "'\\\\'"
            })).to.equal('\\');
            expect(stringExpression.resolve.bind(undefined, {}, {
                value: '3'
            })).to.throw();
            expect(stringExpression.resolve.bind(undefined, {}, {
                value: 'abc'
            })).to.throw();
            expect(stringExpression.resolve.bind(undefined, {}, {
                value: '{abc'
            })).to.throw();
            expect(stringExpression.resolve.bind(undefined, {}, {
                value: 'abc}'
            })).to.throw();
            expect(stringExpression.resolve.bind(undefined, {}, {
                value: '}abc{'
            })).to.throw();
            expect(stringExpression.resolve.bind(undefined, {}, {
                value: '{{abc}}'
            })).to.throw();
            expect(stringExpression.resolve.bind(undefined, {}, {
                value: '"'
            })).to.throw();
            expect(stringExpression.resolve.bind(undefined, {}, {
                value: '`'
            })).to.throw();
            expect(stringExpression.resolve.bind(undefined, {}, {
                value: "'"
            })).to.throw();
            expect(stringExpression.resolve.bind(undefined, {}, {
                value: '{'
            })).to.throw();
            expect(stringExpression.resolve.bind(undefined, {}, {
                value: '}'
            })).to.throw();
        }
    });
    it('resolves value expressions', () => {
        expect(!!valueExpression.resolve).to.equal(true);
        expect(typeof valueExpression.resolve).to.equal('function');
        if (valueExpression.resolve) {
            expect(valueExpression.resolve(undefined, {
                value: 'abc'
            })).to.equal('abc');
            expect(valueExpression.resolve(undefined, {
                value: 'abc   '
            })).to.equal('abc');
            expect(valueExpression.resolve(undefined, {
                value: 'abc\\ \\ \\ '
            })).to.equal('abc   ');
            expect(valueExpression.resolve(undefined, {
                value: '\\ \\ \\ abc'
            })).to.equal('   abc');
            expect(valueExpression.resolve(undefined, {
                value: 'a\\ bc'
            })).to.equal('a bc');
            expect(valueExpression.resolve(undefined, {
                value: '\\\\'
            })).to.equal('\\');
            expect(valueExpression.resolve(undefined, {
                value: 'abc\\\\'
            })).to.equal('abc\\');
            expect(valueExpression.resolve(undefined, {
                value: '123'
            })).to.equal(123);
            expect(valueExpression.resolve(undefined, {
                value: '123.45'
            })).to.equal(123.45);
            expect(valueExpression.resolve(undefined, {
                value: '1E6'
            })).to.equal(1000000);
            expect(valueExpression.resolve(undefined, {
                value: '0x100'
            })).to.equal(256);
            expect(valueExpression.resolve(undefined, {
                value: '\\{abc'
            })).to.equal('{abc');
            expect(valueExpression.resolve(undefined, {
                value: 'abc\\}'
            })).to.equal('abc}');
            expect(valueExpression.resolve(undefined, {
                value: '\\}abc\\{'
            })).to.equal('}abc{');
            expect(valueExpression.resolve(undefined, {
                value: '\\{\\{abc\\}\\}'
            })).to.equal('{{abc}}');
            expect(valueExpression.resolve.bind(undefined, {}, {
                value: '{abc'
            })).to.throw();
            expect(valueExpression.resolve.bind(undefined, {}, {
                value: 'abc}'
            })).to.throw();
            expect(valueExpression.resolve.bind(undefined, {}, {
                value: '}abc{'
            })).to.throw();
            expect(valueExpression.resolve.bind(undefined, {}, {
                value: '{{abc}}'
            })).to.throw();
            expect(valueExpression.resolve.bind(undefined, {}, {
                value: '"'
            })).to.throw();
            expect(valueExpression.resolve.bind(undefined, {}, {
                value: '`'
            })).to.throw();
            expect(valueExpression.resolve.bind(undefined, {}, {
                value: "'"
            })).to.throw();
            expect(valueExpression.resolve.bind(undefined, {}, {
                value: '{'
            })).to.throw();
            expect(valueExpression.resolve.bind(undefined, {}, {
                value: '}'
            })).to.throw();
        }
    });
});
